87	void SfuUnit::stage_fwd_window(uint32_t wid, const Scheduler::FwdWave& wave) {
88	#ifdef VX_GFX_WINDOW_ENABLE
89		// P2: the record is just {pos_mask, pid}; the FS recomputes per-corner edge
90		// values from the primitive edges + the quad origin (no bcoords seeded).
91		constexpr uint32_t B = GfxWindow::FRAG_SLOT_BASE;
92		for (uint32_t t = 0; t < VX_CFG_NUM_THREADS; ++t) {
93			if (!wave.tmask.test(t)) continue;
94			const auto& p = wave.payload[t];
95			gfx_window_.set(wid, t, B + 0, p.pos_mask);
96			gfx_window_.set(wid, t, B + 1, p.pid);
97		}
98	#else
99		(void)wid; (void)wave;
100	#endif
101	}
